def transforms(a):
 a=np.array(a,dtype=int)
 return [np.rot90(a,k) for k in range(4)] + [np.rot90(np.fliplr(a),k) for k in range(4)]
# square transforms equal dimensions; see exact AND / XOR possibilities consistent
