# feature distribution at output positions and all cells, for neighbor sums (8-neighborhood)
for idx,(A,B,O) in enumerate(examples):
 A=np.array(A); B=np.array(B); O=np.array(O)
 print('ex',idx+1)
 for r,c in zip(*np.where(O)):
  def ns(X):return int(X[max(0,r-1):min(4,r+2),max(0,c-1):min(4,c+2)].sum()-X[r,c])
  print((r,c),'bits',A[r,c],B[r,c], 'nbr',ns(A),ns(B),'row',A[r].sum(),B[r].sum(),'col',A[:,c].sum(),B[:,c].sum())

found={op:[] for op in ['and','xor','or','diff']}
for i in range(8):
 for j in range(8):
  for dy in range(-3,4):
   for dx in range(-3,4):
    ok={op:True for op in found}
    for A,B,O in examples:
     x=transforms(A)[i]; yy=np.zeros((4,4),dtype=int); y=transforms(B)[j]
     for r in range(4):
      for c in range(4):
